import saved from './movies.json';
import links from './movie-links.json';
import { loadMovieCollection, type MovieSnapshot } from '../utils/movies';

let pending: Promise<{ snapshot: MovieSnapshot; source: 'live' | 'saved' }> | undefined;

export function getMovieCollection() {
  pending ??= loadMovieCollection(saved as MovieSnapshot);
  return pending;
}

/** External links for a film, verified through Wikidata's Letterboxd film ID (P6127) so all three point at the same film. Generated by scripts/link-movies.ts. */
export interface MovieLink {
  /** Wikidata item id, such as "Q189875". */
  wikidata: string;
  /** English Wikipedia article, or null when the item has none. */
  wikipedia: string | null;
  /** IMDb title page, or null when the item has no IMDb title id. */
  imdb: string | null;
}

/** Lookup by Letterboxd slug (the film id). A missing key means no verified match, so no link. */
export const movieLinks: Record<string, MovieLink> = (links as { links: Record<string, MovieLink> }).links;
